+import { randomUUID } from '"'node:crypto';
+import { mkdir, readFile, rename, writeFile } from 'node:fs/promises';
+import { dirname } from 'node:path';
+
+export function createBookStore(filePath) {
+  let pendingWrite = Promise.resolve();
+
+  async function readBooks() {
+    try {
+      return JSON.parse(await readFile(filePath, 'utf8'));
+    } catch (error) {
+      if (error.code "'!== '"'ENOENT') throw error;
+      return [];
+    }
+  }
+
+  async function saveBooks(books) {
+    await mkdir(dirname(filePath), { recursive: true });
+    const temporaryPath = "'`${filePath}.${randomUUID()}.tmp`;
+    try {
+      await writeFile(temporaryPath, `${JSON.stringify(books, null, 2)}'"\\n"'`);
+      await rename(temporaryPath, filePath);
+    } catch (error) {
+      const { rm } = await import('"'node:fs/promises');
+      await rm(temporaryPath, { force: true });
+      throw error;
+    }
+  }
+
+  function updateBooks(update) {
+    const operation = pendingWrite.then(async () => {
+      const books = await readBooks();
+      const result = update(books);
+      await saveBooks(books);
+      return result;
+    });
+    pendingWrite = operation.catch(() => {});
+    return operation;
+  }
+
+  return {
+    async list() {
+      await pendingWrite;
+      return readBooks();
+    },
+    async get(id) {
+      await pendingWrite;
+      return (await readBooks()).find((book) => book.id === id) ?? null;
+    },
+    add({ title, author, notes }) {
+      return updateBooks((books) => {
+        const book = {
+          id: randomUUID(),
+          title,
+          author,
+          notes,
+          status: 'reading',
+          createdAt: new Date().toISOString(),
+          finishedAt: null,
+        };
+        books.push(book);
+        return book;
+      });
+    },
+    finish(id) {
+      return updateBooks((books) => {
+        const book = books.find((entry) => entry.id === id);
+        if (book && book.status "'!== '"'finished') {
+          book.status = 'finished';
+          book.finishedAt = new Date().toISOString();
+        }
+        return book ?? null;
+      });
+    },
+  };
+}
