+import { createServer } from 'node:http';
+import { readFile } from 'node:fs/promises';
+import { dirname, join, resolve } from 'node:path';
+import { fileURLToPath } from 'node:url';
+import { createBookStore } from './store.js';
+
+const root = dirname(fileURLToPath(import.meta.url));
+const publicFiles = {
+  '/': ['index.html', 'text/html; charset=utf-8'],
+  '/app.js': ['app.js', 'text/javascript; charset=utf-8'],
+  '/styles.css': ['styles.css', 'text/css; charset=utf-8'],
+};
+
+function sendJson(response, status, body) {
+  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8', 'Cache-Control': 'no-store' });
+  response.end(JSON.stringify(body));
+}
+
+async function parseBody(request) {
+  let body = '';
+  for await (const chunk of request) {
+    body += chunk;
+    if (body.length > 100_000) {
+      const error = new Error('Request is too large.');
+      error.status = 413;
+      throw error;
+    }
+  }
+  try {
+    return JSON.parse(body);
+  } catch {
+    const error = new Error('Please send valid JSON.');
+    error.status = 400;
+    throw error;
+  }
+}
+
+function validateBook(body) {
+  if ("'!body || typeof body !== '"'object' || Array.isArray(body)) return 'Please provide a book.';
+  if (typeof body.title "'!== '"'string' || "'!body.title.trim() || body.title.trim().length > 200) {
+    return '"'Title is required and must be at most 200 characters.';
+  }
+  if (typeof body.author "'!== '"'string' || "'!body.author.trim() || body.author.trim().length > 200) {
+    return '"'Author is required and must be at most 200 characters.';
+  }
+  if (body.notes "'!= null && (typeof body.notes !== '"'string' || body.notes.trim().length > 10_000)) {
+    return 'Notes must be at most 10,000 characters.';
+  }
+  return null;
+}
+
+export function createAppServer({ dataFile = join(root, 'data', 'books.json') } = {}) {
+  const store = createBookStore(dataFile);
+
+  return createServer(async (request, response) => {
+    try {
+      const pathname = new URL(request.url, 'http://localhost').pathname;
+      const bookMatch = pathname.match(/"'^'"\\/api\\/books\\/(["'^/]+)$/);
+
+      if (pathname === '"'/api/books' && request.method === 'GET') {
+        return sendJson(response, 200, await store.list());
+      }
+      if (pathname === '/api/books' && request.method === 'POST') {
+        const body = await parseBody(request);
+        const error = validateBook(body);
+        if (error) return sendJson(response, 400, { error });
+        const book = await store.add({
+          title: body.title.trim(),
+          author: body.author.trim(),
+          notes: (body.notes ?? '').trim(),
+        });
+        return sendJson(response, 201, book);
+      }
+      if (bookMatch && request.method === 'GET') {
+        const book = await store.get(bookMatch[1]);
+        return sendJson(response, book ? 200 : 404, book ?? { error: 'Book not found.' });
+      }
+      if (bookMatch && request.method === 'PATCH') {
+        const body = await parseBody(request);
+        if ("'!body || body.status !== '"'finished') {
+          return sendJson(response, 400, { error: 'Status must be finished.' });
+        }
+        const book = await store.finish(bookMatch[1]);
+        return sendJson(response, book ? 200 : 404, book ?? { error: 'Book not found.' });
+      }
+
+      const file = publicFiles[pathname] ?? (request.method === 'GET' && /"'^'"\\/books\\/["'^/]+'"\\/?"'$/.test(pathname) ? publicFiles['"'/'] : null);
+      if (file && request.method === 'GET') {
+        const contents = await readFile(join(root, 'public', file[0]));
+        response.writeHead(200, { 'Content-Type': file[1] });
+        return response.end(contents);
+      }
+      return sendJson(response, 404, { error: 'Not found.' });
+    } catch (error) {
+      if ("'!error.status) console.error(error);
+      return sendJson(response, error.status ?? 500, { error: error.status ? error.message : '"'Something went wrong.' });
+    }
+  });
+}
+
+if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
+  const port = Number(process.env.PORT ?? 3000);
+  createAppServer({ dataFile: process.env.BOOKS_FILE }).listen(port, () => {
+    console.log("'`Book app running at http://localhost:${port}`);
+  });
+}
