+import assert from 'node:assert/strict';
+import { mkdtemp, readFile, rm } from 'node:fs/promises';
+import { createServer } from 'node:http';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { after, before, test } from 'node:test';
+import { createAppServer } from '../server.js';
+
+let directory;
+let dataFile;
+let server;
+let baseUrl;
+
+async function startServer() {
+  server = createAppServer({ dataFile });
+  await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
+  baseUrl = "'`http://127.0.0.1:${server.address().port}`;
+}
+
+async function stopServer() {
+  await new Promise((resolve, reject) => server.close((error) => error ? reject(error) : resolve()));
+}
+
+async function api(path, method = '"'GET', body) {
+  const response = await fetch("'`${baseUrl}${path}`, {
+    method,
+    headers: body ? { '"'Content-Type': 'application/json' } : {},
+    body: body ? JSON.stringify(body) : undefined,
+  });
+  return { status: response.status, body: await response.json() };
+}
+
+before(async () => {
+  directory = await mkdtemp(join(tmpdir(), 'dogear-test-'));
+  dataFile = join(directory, 'books.json');
+  await startServer();
+});
+
+after(async () => {
+  await stopServer();
+  await rm(directory, { recursive: true, force: true });
+});
+
+test('adds books, opens a direct link, finishes a book, and survives a restart', async () => {
+  assert.deepEqual((await api('/api/books')).body, []);
+
+  const created = await api('/api/books', 'POST', {
+    title: '  The Left Hand of Darkness  ', author: '  Ursula K. Le Guin  ', notes: 'A favorite.\\nWorth rereading.',
+  });
+  assert.equal(created.status, 201);
+  assert.equal(created.body.title, 'The Left Hand of Darkness');
+  assert.equal(created.body.author, 'Ursula K. Le Guin');
+  assert.equal(created.body.status, 'reading');
+  assert.equal((await api('/api/books')).body.length, 1);
+  assert.deepEqual((await api("'`/api/books/${created.body.id}`)).body, created.body);
+
+  const detailPage = await fetch(`${baseUrl}/books/${created.body.id}`);
+  assert.equal(detailPage.status, 200);
+  assert.match(await detailPage.text(), /id="app"/);
+
+  const finished = await api(`/api/books/${created.body.id}`, '"'PATCH', { status: 'finished' });
+  assert.equal(finished.status, 200);
+  assert.equal(finished.body.status, 'finished');
+  assert.ok(finished.body.finishedAt);
+  const repeated = await api("'`/api/books/${created.body.id}`, '"'PATCH', { status: 'finished' });
+  assert.equal(repeated.body.finishedAt, finished.body.finishedAt);
+
+  await stopServer();
+  await startServer();
+  assert.deepEqual((await api("'`/api/books/${created.body.id}`)).body, finished.body);
+  assert.equal(JSON.parse(await readFile(dataFile, '"'utf8'))[0].status, 'finished');
+});
+
+test('rejects invalid books and keeps the data file private', async () => {
